def is_operator(i):
	return i in ['*', '^', '/', '+', '-']

def constructTree(postfix):
	stack = []
	for i in postfix:
		if not is_operator(i):
			q = et(i + ' ')
			stack.append(q)
		else:
			right_child = stack.pop()
			left_child = stack.pop()
			q = et(i + ' ')
			q.left = left_child
			q.right = right_child
			stack.append(q)
	return stack.pop()
